  'home.revamp.hero.micro' : { en: 'Free decode in 60 seconds · Full written guidebooks when you want depth', es: 'Decodificación gratis en 60 segundos · Guías escritas completas cuando quieras profundidad' },
  'home.revamp.hero.sub.full' : { en: 'SSC is a new system of numerology, built from bridging it with metaphysics and simulation theory. Start with a free numerology calculator for your Life Path and six more frequencies from birth date and name — a map you can actually apply.', es: 'SSC es un nuevo sistema de numerología, construido al unirla con la metafísica y la teoría de la simulación. Empieza con una calculadora gratuita de numerología para tu Camino de Vida y seis frecuencias más a partir de tu fecha y nombre de nacimiento — un mapa que sí puedes aplicar.' },
  'home.revamp.hero.sub.short' : { en: 'Free numerology calculator for your Life Path — metaphysics and simulation theory rebuilt as a map you can apply.', es: 'Calculadora gratuita de numerología para tu Camino de Vida — metafísica y teoría de la simulación reconstruidas como un mapa que puedes aplicar.' },
  'home.revamp.hero.title' : { en: 'Using Numerology to<br><span>Map out Life Direction</span>', es: 'Usando Numerología para<br><span>Mapear la Dirección de Vida</span>' },
