  'home.revamp.install.step3' : { en: 'Install Source Code: Life', es: 'Instala Source Code: Life' },
  'home.revamp.install.summary' : { en: 'Android beta — three steps', es: 'Beta de Android — tres pasos' },
  'home.revamp.scl.body' : { en: 'Our app uses your numerology blueprint to generate:<ul class="hp-scl-list"><li>7 personalized life quests - tiered to expand as you grow through experience</li><li>Your starting stats (strengths, patterns, growth edges)</li><li>Your inherited skills</li><li>A real-world quest map to inspire adventure and connection with other adventurers!</li></ul>No guesswork or wandering anymore; just a clearer sense of where you are—and what to do about it.', es: 'Nuestra app usa tu blueprint de numerología para generar:<ul class="hp-scl-list"><li>7 misiones de vida personalizadas — con niveles que se expanden conforme creces con la experiencia</li><li>Tus stats iniciales (fortalezas, patrones, bordes de crecimiento)</li><li>Tus habilidades heredadas</li><li>¡Un mapa de misiones en el mundo real para inspirar aventura y conexión con otros aventureros!</li></ul>Sin más adivinanzas ni deambular; solo una idea más clara de dónde estás — y qué hacer al respecto.' },
  'home.revamp.scl.eyebrow' : { en: '> Source Code: Life Quest app', es: '> App Source Code: Life Quest' },
  'home.revamp.scl.note' : { en: 'Beta is live on Android. Join the testers and start your quests now.', es: 'La beta ya está en Android. Únete a los testers y empieza tus misiones ahora.' },
  'home.revamp.scl.prototype' : { en: '> Try the Prototype', es: '> Prueba el Prototipo' },
  'home.revamp.scl.title' : { en: 'Play your numerology blueprint in the game of life', es: 'Juega tu blueprint de numerología en el juego de la vida' },
