  'home.revamp.services.guidebook.desc' : { en: 'All seven frequencies decoded in a written guidebook you keep forever.', es: 'Las siete frecuencias decodificadas en una guía escrita que conservas para siempre.' },
  'home.revamp.services.link' : { en: 'Learn more →', es: 'Saber más →' },
  'home.revamp.services.membership' : { en: 'Learn the System', es: 'Aprende el Sistema' },
  'home.revamp.services.membership.desc' : { en: 'Monthly membership to decode patterns yourself — the full SSC framework.', es: 'Membresía mensual para decodificar patrones por ti mismo — el marco completo de SSC.' },
  'home.revamp.services.sub' : { en: 'Every path starts with your seven frequencies. Choose how far you want to go.', es: 'Todo camino empieza con tus siete frecuencias. Elige hasta dónde quieres llegar.' },
  'home.revamp.services.title' : { en: 'Beyond the Free Calculator', es: 'Más Allá de la Calculadora Gratuita' },
  'home.revamp.ssc.body' : { en: 'Your Blueprint sits inside the Codex. SSC decodes seven frequencies from your birth date and name — each one a layer of who you are and how your life is structured. Your External Circuit reflects the lessons and patterns the world brings you. Your Internal Circuit reveals the drives and tools you carry within.', es: 'Tu Blueprint vive dentro del Códice. SSC decodifica siete frecuencias a partir de tu fecha y nombre de nacimiento — cada una una capa de quién eres y cómo está estructurada tu vida. Tu Circuito Externo refleja las lecciones y patrones que el mundo te trae. Tu Circuito Interno revela los impulsos y herramientas que llevas dentro.' },
  'home.revamp.ssc.cta.primary' : { en: '▶&nbsp;Find Your Blueprint', es: '▶&nbsp;Encuentra Tu Blueprint' },
  'home.revamp.ssc.cta.secondary' : { en: 'Triune Trinity Blueprint →', es: 'Blueprint de la Trinidad Triuna →' },
