  'home.revamp.sticky' : { en: 'Find Your Blueprint', es: 'Encuentra Tu Blueprint' },
  'home.step1.body' : { en: 'Provide your full birth name and date of birth. Use the name on your birth certificate.', es: 'Proporciona tu nombre completo de nacimiento y fecha de nacimiento. Usa el nombre de tu acta de nacimiento.' },
  'home.step1.title' : { en: 'Enter Your Details', es: 'Ingresa Tus Datos' },
  'home.step2.body' : { en: 'Our system applies Pythagorean numerology principles to derive each of your seven core numbers.', es: 'Nuestro sistema aplica los principios de la numerología pitagórica para derivar cada uno de tus siete números centrales.' },
  'home.step2.title' : { en: 'Calculate Your Frequencies', es: 'Calcula Tus Frecuencias' },
  'home.step3.body' : { en: 'Each number is decoded with rich layered interpretations — themes, archetypes, strengths, and shadows.', es: 'Cada número es descifrado con interpretaciones profundas y en capas — temas, arquetipos, fortalezas y sombras.' },
