  // ── Privacy ────────────────────────────────────────
  'privacy.eyebrow' : { en: 'Legal', es: 'Legal' },
  'privacy.plain' : { en: 'In plain language:', es: 'En términos simples:' },
  'privacy.plain.body' : { en: 'We collect the data needed to run the site, deliver purchases, improve the experience, and measure ads. We do not sell your personal information.', es: 'Recopilamos los datos necesarios para operar el sitio, entregar compras, mejorar la experiencia y medir anuncios. No vendemos tu informacion personal.' },
  'privacy.s1.body' : { en: 'Simulation Source Code ("SSC") operates the SSC Numerology application and associated website.', es: 'Simulation Source Code ("SSC") opera la aplicación SSC Numerología y el sitio web asociado.' },
  'privacy.s1.title' : { en: '1  Who We Are', es: '1  Quiénes Somos' },
  'privacy.s2.body' : { en: 'We collect only what is necessary: calculator inputs processed in your browser, contact and birth details you voluntarily submit for email delivery or paid reports, purchase/session information from Stripe, usage analytics, and technical data such as device, browser, pages visited, and approximate location.', es: 'Solo recopilamos lo necesario: entradas de la calculadora procesadas en tu navegador, datos de contacto y nacimiento que envias voluntariamente para entrega por correo o reportes pagados, informacion de compra/sesion de Stripe, analitica de uso y datos tecnicos como dispositivo, navegador, paginas visitadas y ubicacion aproximada.' },
  'privacy.s2.title' : { en: '2  Information We Collect', es: '2  Información que Recopilamos' },
  'privacy.s3.body' : { en: 'Information is used to provide and improve the service, generate and deliver reports, process purchases, send requested communications, measure site performance, understand which pages and ads are effective, and comply with legal obligations. We do not sell or trade your personal information.', es: 'La informacion se usa para proporcionar y mejorar el servicio, generar y entregar reportes, procesar compras, enviar comunicaciones solicitadas, medir el rendimiento del sitio, entender que paginas y anuncios funcionan, y cumplir obligaciones legales. No vendemos ni intercambiamos tu informacion personal.' },
  'privacy.s3.title' : { en: '3  How We Use Your Information', es: '3  Cómo Usamos Tu Información' },
  'privacy.s4.body' : { en: 'Free calculator results are generated in your browser. If you submit your email or purchase a report, the information needed to fulfill that request may be sent to our service providers and retained as needed for delivery, support, fraud prevention, taxes, and legal records.', es: 'Los resultados gratuitos de la calculadora se generan en tu navegador. Si envias tu correo o compras un reporte, la informacion necesaria para cumplir esa solicitud puede enviarse a nuestros proveedores de servicio y conservarse segun sea necesario para entrega, soporte, prevencion de fraude, impuestos y registros legales.' },
  'privacy.s4.title' : { en: 'Data Storage &amp; Security', es: 'Almacenamiento y Seguridad de Datos' },
  'privacy.s5.body' : { en: 'We use service providers including Stripe for payments, Cloudflare for hosting/security, Resend and Google Sheets/Apps Script for email and order workflows, Google Analytics 4 for traffic and ecommerce measurement, and Meta Pixel/Conversions API for ad measurement and purchase-event deduplication. These services may use cookies, pixels, or similar technologies according to their own policies.', es: 'Usamos proveedores de servicio como Stripe para pagos, Cloudflare para alojamiento/seguridad, Resend y Google Sheets/Apps Script para flujos de correo y pedidos, Google Analytics 4 para medicion de trafico y comercio electronico, y Meta Pixel/Conversions API para medicion de anuncios y deduplicacion de eventos de compra. Estos servicios pueden usar cookies, pixeles o tecnologias similares segun sus propias politicas.' },
  'privacy.s5.title' : { en: 'Third-Party Services', es: 'Servicios de Terceros' },
  'privacy.s6.body' : { en: 'You may have rights to access, correct, delete, or port your data. Contact us — we respond within 30 days.', es: 'Puedes tener derechos para acceder, corregir, eliminar o portar tus datos. Contáctanos — respondemos en un plazo de 30 días.' },
  'privacy.s6.title' : { en: 'Your Rights', es: 'Tus Derechos' },
  'privacy.s7.body' : { en: 'The app is not directed at children under 13. We do not knowingly collect their personal information.', es: 'La app no está dirigida a menores de 13 años. No recopilamos a sabiendas su información personal.' },
  'privacy.s7.title' : { en: 'Children\'s Privacy', es: 'Privacidad de Menores' },
  'privacy.s8.body' : { en: 'When we update this policy we will revise the date above and notify users of significant changes through the app.', es: 'Cuando actualicemos esta política revisaremos la fecha de arriba y notificaremos a los usuarios de cambios significativos a través de la app.' },
  'privacy.s8.title' : { en: 'Changes to This Policy', es: 'Cambios a Esta Política' },
  'privacy.s9.title' : { en: 'Contact', es: 'Contacto' },
  'privacy.title' : { en: 'Privacy Policy', es: 'Política de Privacidad' },
  'privacy.updated' : { en: 'Last updated: August 5, 2026', es: 'Ultima actualizacion: 5 de agosto de 2026' },

